{
  "name": "rf_cmd_event_notify",
  "confidence": "medium",
  "docstring": "Creates and dispatches an RF command completion event by checking the command context, allocating/notifying an event object, filling its payload with a 6-byte address and timing/sequence fields, then dispatching it via the BLE event path.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "ctx",
    "a2": "addr6",
    "v2": "cmd_ptr",
    "v5": "cmd_type",
    "v7": "event_ptr",
    "v8": "event_payload",
    "v10": "event_seq",
    "v14": "timer_ctx"
  },
  "struct_hints": [
    {
      "offset": 72,
      "meaning": "ctx + 72: current RF command/event pointer"
    },
    {
      "offset": 4,
      "meaning": "cmd_ptr + 4: RF command type"
    },
    {
      "offset": 1224,
      "meaning": "ctx + 1224: command/activity flag used in event condition"
    },
    {
      "offset": 100,
      "meaning": "ctx + 100: 32-bit timestamp or start tick copied into event payload"
    },
    {
      "offset": 104,
      "meaning": "ctx + 104: 16-bit RF channel or scan/command parameter copied into event payload"
    },
    {
      "offset": 107,
      "meaning": "ctx + 107: status/RSSI-like byte copied into event header"
    },
    {
      "offset": 72,
      "meaning": "event_ptr + 72: pointer to event payload buffer"
    },
    {
      "offset": 28,
      "meaning": "event_ptr + 28: event status byte"
    },
    {
      "offset": 29,
      "meaning": "event_ptr + 29: event length sentinel set to -1/0xFF"
    },
    {
      "offset": 76,
      "meaning": "event_ptr + 76: timer context pointer"
    },
    {
      "offset": 92,
      "meaning": "event_ptr + 92: source context pointer"
    },
    {
      "offset": 108,
      "meaning": "event_payload + 108: report status/flags byte, written as 0xC0"
    },
    {
      "offset": 112,
      "meaning": "event_payload + 112: 6-byte destination or scanned address copied from addr6"
    },
    {
      "offset": 118,
      "meaning": "event_payload + 118: 32-bit timestamp field"
    },
    {
      "offset": 122,
      "meaning": "event_payload + 122: 16-bit channel or parameter field"
    },
    {
      "offset": 124,
      "meaning": "event_payload + 124: 32-bit timestamp field"
    },
    {
      "offset": 128,
      "meaning": "event_payload + 128: duplicate 16-bit channel/parameter field"
    },
    {
      "offset": 130,
      "meaning": "event_payload + 130: sequence number scaled by 16"
    },
    {
      "offset": 132,
      "meaning": "event_payload + 132: fixed payload length/status field set to 7"
    },
    {
      "offset": 28,
      "meaning": "timer_ctx + 28: current timer tick or timestamp low word"
    },
    {
      "offset": 32,
      "meaning": "timer_ctx + 32: 64-bit timer expiry or event deadline"
    }
  ]
}
